(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*8 + Math.cos((y+w1y)*0.01+t*0.1)*6;
  const w2y = Math.cos((y+w1y)*0.014+t*0.12)*8 + Math.sin((x+w1x)*0.011-t*0.18)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*50,0.085,1.8],
    [200+Math.sin(t*0.25+6)*110,220+Math.cos(t*0.45+3)*60,0.095,2.4]
  ];
  let aS=0,iS=0,crs=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp),i=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a;iS+=i;crs+=a*i*0.5;
  }
  const act=aS/9,inh=iS/9,cr=crs/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+Math.sin(sy*0.05+t)*0.3+t*0.6)*0.15
    +Math.sin(sy*0.07+Math.cos(sx*0.04-t)*0.25-t*0.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.03-ang*5+t*0.8)*0.7+Math.sin(dist*0.06+ang*2-t*2)*0.5)*0.25;
  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)*Math.sin((sx+sy)*0.1+t)*0.3
    +Math.sin(sx*0.35-t*1.5)*Math.sin(sy*0.3+t*1.2)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cr*0.8+moire)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    +Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const pulse=Math.sin(dist*0.04-t*2.5)*Math.exp(-dist*0.005)*0.4;
  const blend=reaction*0.6+cell*0.2+pulse*0.2,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,80],[15,75,110],[20,130,130],[45,165,120],
    [140,190,80],[220,195,55],[230,145,50],[210,95,60],[175,55,70],
    [120,30,65],[65,15,55],[20,10,48],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(cr)*0.1;
  const edge=Math.abs(reaction)>0.75?1.2:(Math.abs(reaction)>0.5?1.05:1.0);
  const vig=1.0-Math.pow(dist/280,2)*0.15;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge*vig)|0
  ];
}
